#include "unity.h"
#include "header.h"
#include "helpers.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void setUp(void) { }
void tearDown(void) { }

void unit_test_get_number_fscanf_failure(void) {
    // Setup: Create a file that is empty or at EOF to cause fscanf to return 0
    const char *lines[] = {""}; // Empty file
    char *filename = helper_create_test_file(lines, 1);
    TEST_ASSERT_NOT_NULL(filename);

    FILE *fp = fopen(filename, "r");
    TEST_ASSERT_NOT_NULL(fp);

    // Read the empty line, moving fp to EOF
    char dummy[100];
    fgets(dummy, sizeof(dummy), fp); // This will read nothing, fp now at EOF

    char buffer[100];
    uint8_t out_int[10] = {0};

    // Test: Call get_number with fp at EOF, fscanf will return 0
    int result = get_number(fp, buffer, out_int);

    // Assertions: Should return -1 as per path 3
    TEST_ASSERT_EQUAL_INT(-1, result);

    // Cleanup
    fclose(fp);
    helper_cleanup_test_file(filename);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_get_number_fscanf_failure);
    return UNITY_END();
}

